ALTER TABLE landing_pages ADD COLUMN subdomain VARCHAR(40) NULL, ADD COLUMN published_subdomain VARCHAR(40) NULL, ADD UNIQUE KEY landing_subdomain_uq (subdomain), ADD UNIQUE KEY landing_published_subdomain_uq (published_subdomain), ADD CONSTRAINT landing_subdomain_ck CHECK (subdomain IS NULL OR subdomain REGEXP '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$'), ADD CONSTRAINT landing_published_subdomain_ck CHECK (published_subdomain IS NULL OR published_subdomain REGEXP '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$')